// Compiles the annotated book file's script entry (packages/reading-model/
// src/export-front.ts) into the IIFE string the export inlines, and writes
// it to a committed generated file. The bytes inside the exported HTML are
// exactly these — the file's script is never hand-written on the server
// side. Run with --check to verify freshness without writing (the
// file-script-fresh test owns that gate; a drift exits 1 and names the
// fixing command).
import { build } from "esbuild";
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const serverRoot = resolve(here, "..");
const entry = resolve(
  serverRoot,
  "../../packages/reading-model/src/export-front.ts"
);
const generated = resolve(serverRoot, "src/export/file-script.generated.ts");

// es2017: the exported file opens wherever its CSS already requires
// (flexbox-era browsers); the entry stays within the no-async subset so
// nothing needs a runtime generator/async lowering. Optional chaining and
// nullish coalescing lower fine.
const result = await build({
  // esbuild writes source-path comments relative to the working dir; pin
  // it so the committed bytes never depend on how this script was invoked
  // (npm --workspace sets cwd to apps/server, a manual run to the root).
  absWorkingDir: resolve(serverRoot, "../.."),
  entryPoints: [entry],
  bundle: true,
  format: "iife",
  target: "es2017",
  charset: "utf8",
  write: false,
  logLevel: "silent",
  outfile: "file-script.js",
});
const script = result.outputFiles[0].text.trim() + "\n";

// The script rides inside an HTML <script> element: a literal "</script"
// sequence (string, regex, or comment) would close the tag early. The
// entry's sources contain none; this guard keeps it true forever.
if (/<\/script/i.test(script)) {
  console.error(
    "build-file-script: the compiled script contains </script — refusing to inline it"
  );
  process.exit(1);
}

const banner = `// Generated by apps/server/scripts/build-file-script.mjs from
// packages/reading-model/src/export-front.ts — do not edit by hand.
// Regenerate: npm run build:file-script --workspace @lingualeaf/server
export const FILE_SCRIPT = ${JSON.stringify(script)};
`;

if (process.argv.includes("--check")) {
  const current = readFileSync(generated, "utf8");
  if (current !== banner) {
    console.error(
      "file-script.generated.ts is stale: export-front.ts changed without a regenerate.\n" +
        "Run: npm run build:file-script --workspace @lingualeaf/server"
    );
    process.exit(1);
  }
  console.log("file-script.generated.ts is fresh");
} else {
  writeFileSync(generated, banner);
  console.log("file-script.generated.ts written");
}
